            "game_id": gid,
            "original_pgn": game[:200] + "..." if len(game) > 200 else game,
            "repaired_pgn": "\n".join(repl),
            "errors_found": errors,
            "critical_position": analyze_critical_position(repaired)
        })

    puzzle_solutions = []
    for p in puzzles:
        sol = solve_puzzle(p['fen'], p['description'])
        puzzle_solutions.append({
            "puzzle_id": p['id'],
            "best_move": sol["best_move"],
            "continuation": sol["continuation"],
            "mate_in": sol["mate_in"]
        })

    output = {
        "repaired_games": repaired_games,
        "puzzle_solutions": puzzle_solutions,
        "analysis_summary": {
            "games_processed": len(games),
            "errors_fixed": total_fixed,
            "puzzles_solved": len(puzzles)
        }
    }

    with open('/workdir/chess_analysis.json', 'w') as f:
        json.dump(output, f, indent=2)
    print(f"Done: {len(games)} games, {total_fixed} errors fixed, {len(puzzles)} puzzles")

if __name__ == '__main__':
    main()
